+import ts from 'typescript';
+
+export function inferSchema(typeNode: ts.TypeNode) {
+  const checker = /* get type checker */;
+  const type = checker.getTypeAtLocation(typeNode);
+
+  const properties = checker.getPropertiesOfType(type);
+  const schema: Record<string, unknown> = {};
+
+  for (const prop of properties) {
+    const propType = checker.getTypeOfSymbolAtLocation(prop, typeNode);
+    schema[prop.name] = tsTypeToZod(propType, checker);
+  }
+
+  return schema;
+}
+
+function tsTypeToZod(type: ts.Type, checker: ts.TypeChecker) {
+  if (type.flags & ts.TypeFlags.String) return 'z.string()';
+  if (type.flags & ts.TypeFlags.Number) return 'z.number()';
+  return 'z.unknown()';
+}
